/**
 * Inlines the slide-deck viewer libraries into the app, so decks render without a CDN and
 * offline (same approach as the LiveKit client bundle). Uses the web app's pinned versions so
 * both render decks the same way (pdf.js legacy build: older phone WebViews lack newer JS):
 *
 *   node scripts/generate-deck-viewer-bundle.mjs
 *
 * Rerun after upgrading pdfjs-dist, pptx-preview or jszip in frontend/.
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const web = join(root, '..', 'frontend', 'node_modules');
const version = (pkg) => JSON.parse(readFileSync(join(web, pkg, 'package.json'), 'utf8')).version;
const read = (path) => readFileSync(join(web, path), 'utf8');

const parts = [
  ['PDFJS_SRC', 'pdfjs-dist', 'pdfjs-dist/legacy/build/pdf.min.mjs'],
  ['PDFJS_WORKER_SRC', 'pdfjs-dist', 'pdfjs-dist/legacy/build/pdf.worker.min.mjs'],
  ['PPTX_PREVIEW_SRC', 'pptx-preview', 'pptx-preview/dist/pptx-preview.umd.js'],
  ['JSZIP_SRC', 'jszip', 'jszip/dist/jszip.min.js'],
];

const out = [
  '// GENERATED by scripts/generate-deck-viewer-bundle.mjs: do not edit by hand.',
  `// pdfjs-dist@${version('pdfjs-dist')}, pptx-preview@${version('pptx-preview')}, jszip@${version('jszip')}`,
  '// (the web app\'s versions), inlined so slide decks render offline in the deck viewer.',
  '',
  ...parts.map(([name, , path]) => `export const ${name} = ${JSON.stringify(read(path))};`),
  '',
].join('\n');

const target = join(root, 'src', 'features', 'classroom', 'utils', 'deck-viewer-bundle.ts');
writeFileSync(target, out);
console.log(`wrote ${target} (${(out.length / 1024 / 1024).toFixed(2)} MB)`);
